query ShopAttributesQuery($channel: String!, $collectionId: ID, $categoryId: ID) {
  attributes(
    channel: $channel
    filter: {inCollection: $collectionId, inCategory: $categoryId, filterableInStorefront: true}
    first: 100
  ) {
    edges {
      node {
        ...Attribute
      }
    }
  }
}

fragment Attribute on Attribute {
  id
  name
  slug
  choices(first: 100) {
    edges {
      node {
        id
        name
        slug
      }
    }
  }
}
